"""Build a local blinded review/scoring page from exported benchmark artifacts."""
import argparse
import html
import json
from pathlib import Path

parser=argparse.ArgumentParser()
parser.add_argument('review_dir',type=Path)
args=parser.parse_args()
root=args.review_dir
rows=json.loads((root/'audit.json').read_text())
criteria=[('Drawing fidelity',40),('Parameterization',20),('Topology',15),('Mesh readiness',15),('Explanation',10)]
cards=[]
for row in rows:
    label=row['label']
    report=(root/label/'report.md').read_text(encoding='utf-8-sig')
    inputs=''.join(f'<label>{name} <span>/{maximum}</span><input type="number" min="0" max="{maximum}" step="1" data-label="{label}" data-max="{maximum}" aria-label="Design {label} {name}" placeholder="Unscored"></label>' for name,maximum in criteria)
    cards.append(f'''<article><h2>Design {label}</h2><img class="cad" src="{label}/cad-preview.png" alt="Actual exported pipe geometry for design {label}"><img class="section" src="{label}/profile.svg" alt="Axial fluid section for design {label}"><p class="pass">Solid + STEP + editability checks passed</p><p>Mesh: {row['mesh']['cells']:,} cells · {row['mesh']['size_mm']:g} mm target · Mesh OK</p><p>{row['tool_invocations']} tool invocations · {row['errors']} tool errors</p><nav><a href="{label}/venturi.FCStd" download>FreeCAD</a><a href="{label}/pipe.step" download>Pipe STEP</a><a href="{label}/fluid.step" download>Fluid STEP</a><a href="{label}/fluid.msh" download>Mesh</a></nav><details><summary>Interpretation and assumptions</summary><pre>{html.escape(report)}</pre></details><div class="scores">{inputs}</div><label>Comments<textarea data-comment="{label}" rows="3"></textarea></label><div class="total" id="total-{label}">Unscored</div></article>''')
page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Venturi CAD review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#182333;font:16px system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:28px}h1{margin:0 0 10px}p{line-height:1.55}.intro{max-width:950px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}article{background:white;border:1px solid #dce2e8;border-radius:12px;padding:20px}h2{margin-top:0}.cad{width:100%;height:170px;object-fit:contain}.section{width:100%;height:110px;object-fit:contain}.pass{color:#176344;font-weight:600}nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}a{color:#225db2}details{margin:15px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;font:14px/1.6 system-ui;max-height:420px;overflow:auto}.scores{display:grid;gap:12px}label{display:block;font-weight:600;font-size:14px}label span{color:#687889}input,textarea{display:block;width:100%;font:inherit;padding:9px;border:1px solid #aebccc;border-radius:5px;margin-top:6px}input:invalid{border:2px solid #ba2525}.total{font-size:24px;font-weight:700;margin-top:18px}.actions{display:flex;gap:12px;margin:24px 0;flex-wrap:wrap}button{border:0;background:#245ca8;color:white;border-radius:6px;padding:12px 18px;font:600 15px system-ui;cursor:pointer}button:disabled{opacity:.5;cursor:default}#source{width:100%;max-width:650px;display:block;margin:auto}.muted{color:#596a7b}@media(max-width:900px){.grid{grid-template-columns:1fr}.cad{height:230px}}
</style></head><body><main><h1>Venturi CAD review</h1><p class="intro">Three independent attempts, shown as A/B/C. All produced the same 130 mm bore profile and assumed a 2 mm wall. Geometry is tied in this constrained test; assess interpretation, assumptions, parameterization and deliverables. Mesh sizes were selected by each agent. A passing mesh check does not establish CFD accuracy.</p><details><summary>Approved source drawing</summary><img id="source" src="source.png" alt="Approved university manual page with dimensions and Venturi figure"></details><p class="muted">Your scores start blank. Model identities remain hidden. Scores persist in this browser; export the CSV or copy the totals to share them in chat.</p><div class="grid">CARDS</div><div class="actions"><button id="export" disabled>Export scores CSV</button><button id="copy" disabled>Copy totals</button></div><p id="state" aria-live="polite">Awaiting your scores.</p></main><script>
const inputs=[...document.querySelectorAll('input')];const comments=[...document.querySelectorAll('textarea')];const key='agent-gym-venturi-review-v1';let cached={};try{cached=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}inputs.forEach((x,i)=>{if(cached.values&&cached.values[i]!==undefined)x.value=cached.values[i]});comments.forEach((x,i)=>{if(cached.comments)x.value=cached.comments[i]||''});
function totals(){return ['A','B','C'].map(label=>{const fields=inputs.filter(x=>x.dataset.label===label);const done=fields.every(x=>x.value!==''&&x.checkValidity());return {label,fields,done,total:done?fields.reduce((a,x)=>a+Number(x.value),0):null}})}
function update(){const rows=totals();rows.forEach(x=>document.getElementById('total-'+x.label).textContent=x.done?x.total+' / 100':'Unscored');const done=rows.every(x=>x.done);document.getElementById('export').disabled=!done;document.getElementById('copy').disabled=!done;document.getElementById('state').textContent=done?'Scores entered. Export or copy them to share.':'Awaiting valid scores for all criteria.';try{localStorage.setItem(key,JSON.stringify({values:inputs.map(x=>x.value),comments:comments.map(x=>x.value)}))}catch(e){}}
inputs.concat(comments).forEach(x=>x.addEventListener('input',update));update();
document.getElementById('export').onclick=()=>{const quote=x=>'"'+String(x).replaceAll('"','""')+'"';const lines=[['design_label','drawing_fidelity_40','parameterization_20','topology_15','mesh_readiness_15','explanation_10','total_100','comments'],...totals().map((x,i)=>[x.label,...x.fields.map(f=>f.value),x.total,comments[i].value])];const blob=new Blob([lines.map(r=>r.map(quote).join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='venturi-human-scores.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
document.getElementById('copy').onclick=async()=>{const text=totals().map(x=>'Design '+x.label+': '+x.total+'/100').join('\n');try{await navigator.clipboard.writeText(text);document.getElementById('state').textContent='Totals copied.'}catch(e){document.getElementById('state').textContent=text}};
</script></body></html>'''.replace('CARDS',''.join(cards))
(root/'index.html').write_text(page,encoding='utf-8')
print(root/'index.html')
